class PlaceOrderService(
    private val orders: OrderRepository,
    private val customers: CustomerRepository,
) {
    suspend fun place(cmd: PlaceOrderCommand): OrderId =
        suspendTransaction {                       // commits on return, rolls back on throw
            val customer = customers.ofId(cmd.customerId)
            val order = customer.placeOrder(cmd.items)   // the aggregate decides
            orders.add(order)
            order.id
        }
}
